import json
from pathlib import Path
x = json.loads(Path('input.json').read_text())
by_id = {r['id']: r for r in x['reports']}
def clip(r):
    return (max(0, r['start']), min(60, r['end']))
def union(intervals):
    result = []
    for a, b in sorted(intervals):
        if a >= b:
            continue
        if result and a <= result[-1][1]:
            result[-1][1] = max(result[-1][1], b)
        else:
            result.append([a, b])
    return result
def minutes(intervals):
    return sum(b-a for a,b in intervals)
retained = []
for r in x['reports']:
    correction = by_id.get(r.get('superseded_by'))
    if r['published'] > x['cutoff']:
        continue
    if correction is not None and correction['published'] <= x['cutoff']:
        continue
    a, b = clip(r)
    if a < b and (r['kind'] == 'uncertain' or (r['kind'] == 'down' and r['authoritative'])):
        retained.append(r)
services = []
fleet = []
for service in sorted(x['services']):
    reports = [r for r in retained if r['service'] == service]
    confirmed = union(clip(r) for r in reports if r['kind'] == 'down')
    possible = union(clip(r) for r in reports)
    coverage = union(clip(r) for r in x['monitors'] if r['service'] == service)
    observed = sum(max(0, min(b,d)-max(a,c)) for a,b in confirmed for c,d in coverage)
    fleet.extend(confirmed)
    services.append({'id': service, 'confirmed_minutes': minutes(confirmed), 'possible_minutes': minutes(possible), 'unobserved_confirmed_minutes': minutes(confirmed)-observed})
print(json.dumps({'services': services, 'fleet_confirmed_minutes': minutes(union(fleet)), 'retained_report_ids': sorted(r['id'] for r in retained)}, separators=(',', ':')))
